/** user-defined types **/

/**
 * How this PC reaches a headset over SSH. A missing pin trusts the first host key it sees.
 */
export type Access = { address: string; user: string; privateKey: string; hostKeyPin: string | null }
export type AudioDeviceDto = { id: string; name: string; deviceType: AudioDeviceType; volume: number; mute: boolean; default: boolean; defaultCommunications: boolean }
export type AudioDeviceType = "Capture" | "Render"
export type BindingOriginData = { localizedControllerType: string; localizedHand: string; localizedInputSource: string; devicePathName: string; inputPathName: string; modeName: string; slotName: string; inputSourceType: string }
/**
 * The headset's hardware brightness in percent, as the helper reports it.
 */
export type Brightness = { 
/**
 * False while the helper has no SteamVR session; nothing else is known then.
 */
runtime: boolean; supported: boolean; min: number | null; max: number | null; 
/**
 * The headset's value, which can lie outside `min` and `max`.
 */
percentage: number | null }
export type Candidate = { name: string; address: string }
/**
 * The headset's color temperature, as the helper reports it.
 */
export type Cct = { 
/**
 * False while the helper has no SteamVR session; nothing else is known then.
 */
available: boolean; 
/**
 * The nearest integer Kelvin on OyasumiVR's curve.
 */
kelvin: number | null; 
/**
 * True when the display gains lie on the curve at `kelvin`.
 */
exact: boolean | null }
/**
 * Checkpoint metadata, serialized camelCase for the frontend.
 */
export type CheckpointMetadata = { formatVersion: number; id: string; storeName: string; appVersion: string; reason: string; createdAt: string; createdAtMillis: number; sequence: number; schemaVersions: Partial<{ [key in string]: number }>; contentChecksum: string; contentSizeBytes: number; contentFile: string; contentFileExists?: boolean }
/**
 * Every mode removes this PC's token file and key lines.
 */
export type CleanupMode = 
/**
 * Also removes the helper when no PC holds a token any more, as a cancelled pairing does.
 */
"unused" | 
/**
 * Also removes the helper, which disconnects every other PC.
 */
"uninstall"
export type CleanupOutcome = { status: "done" } | 
/**
 * The headset rejects this PC's key, so the cleanup changed nothing on it.
 */
{ status: "rejected" } | { status: "unreachable" } | { status: "hostKeyChanged" } | { status: "failed"; message: string }
export type CleanupRequest = { access: Access; pcId: string; publicKey: string; mode: CleanupMode }
export type Control = "brightness" | "cct"
export type Controller = { serial: string; connected: boolean }
export type DebugSnapshot = { quaternion: [number, number, number, number]; geometry: PoseGeometry; rawPose: SleepingPose; stablePose: SleepingPose }
export type DisableResult = { result: "ok" } | { result: "cleanupFailed"; reason: string }
export type DisconnectControllerError = "runtimeUnavailable" | "writeFailed" | 
/**
 * No open connection, or it closed before the helper replied.
 */
"offline"
export type EnableResult = { result: "ok" } | 
/**
 * The user dismissed the UAC prompt.
 */
{ result: "promptDeclined" } | { result: "installFailed" } | { result: "taskFailed"; reason: string; code: string } | 
/**
 * Not an administrator account, so these features stay unavailable.
 */
{ result: "notSupported" }
export type FadeError = "unsupported" | "runtimeUnavailable" | "writeFailed" | 
/**
 * No open connection, or it closed before the helper replied.
 */
"offline"
/**
 * A fade for the helper. `simple` is a simple-mode curve from and to, for brightness only.
 */
export type FadeRequest = { control: Control; operation: string; target: number; durationMs: number; simple: SimpleCurve | null }
export type Identity = { serial: string; model: string; manufacturer: string }
export type JsonValue = null | boolean | number | string | JsonValue[] | Partial<{ [key in string]: JsonValue }>
